/// Browser bindings for the app agent's hub membership.
///
/// The socket uses `web_socket_channel` (no `dart:io`) and the identity uses
/// the app's persistent [ExecutionEnv] sandbox, which is IndexedDB-backed on
/// web. Enrollment authentication is the hub's browser bearer equivalent,
/// isolated in [hubUrlWithBrowserBearer].
library;

import 'dart:async';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';
import 'package:web_socket_channel/web_socket_channel.dart';

/// Browser hub connections and persistent identities are fully supported.
const bool agentNetworkSupported = true;

/// The platform transport. Tests may inject a [WebHubSocketConnector] into
/// [WebHubTransport] instead of opening a real browser socket.
HubTransport? get platformHubTransport => const WebHubTransport();

/// The identity lives in the app sandbox, scoped by the caller exactly as on
/// native platforms.
String? identityPathFor(String sandboxRoot) => '$sandboxRoot/hub_identity';

/// Loads a stable identity through the web sandbox filesystem, creating and
/// persisting it on first use. A corrupt record is replaced just like the
/// native file-backed loader; a failed write is surfaced so an unpersisted
/// identity is never used as though it were stable.
Future<HubIdentity?> loadOrCreateIdentity(
  ExecutionEnv env,
  String? path,
) async {
  if (path == null) return null;
  final stored = (await env.readTextFile(path)).valueOrNull;
  if (stored != null) {
    try {
      return await hubIdentityFromKeyFile(stored);
    } on Object {
      // Regenerate below. Never log the record: it contains private keys.
    }
  }
  final identity = await HubIdentity.generate();
  final result = await env.writeFile(
    path,
    await hubIdentityToKeyFile(identity),
  );
  if (result case Err(:final error)) throw error;
  return identity;
}

/// Injectable browser socket boundary. The URI passed to an authenticated
/// connector contains a credential and must never be logged or stringified
/// into an error.
typedef WebHubSocketConnector = Future<HubSocket> Function(Uri url);

/// A real browser [HubTransport] with bearer-equivalent enrollment auth.
final class WebHubTransport implements HubTransport, HubBearerTransport {
  const WebHubTransport({WebHubSocketConnector connector = _defaultConnector})
    // Public parameter name, private storage: keep the injection seam usable.
    // ignore: prefer_initializing_formals
    : _connector = connector;

  final WebHubSocketConnector _connector;

  @override
  Future<HubSocket> connect(Uri url) => _connect(url);

  @override
  Future<HubSocket> connectWithBearer(Uri url, String secret) =>
      _connect(hubUrlWithBrowserBearer(url, secret));

  Future<HubSocket> _connect(Uri url) async {
    try {
      return await _connector(url);
    } on Object {
      // Browser and server errors can echo the complete upgrade URI. Never
      // propagate one: an authenticated URI carries the enrollment secret.
      throw StateError('hub WebSocket connection failed');
    }
  }

  static Future<HubSocket> _defaultConnector(Uri url) async {
    final channel = WebSocketChannel.connect(url);
    try {
      await channel.ready;
      return WebHubSocket(channel);
    } on Object {
      try {
        await channel.sink.close();
      } on Object {
        // The original failure is sanitized by [_connect].
      }
      rethrow;
    }
  }
}

/// One text-frame browser socket. Binary frames are dropped at the boundary,
/// matching the native transport and the hub's text-only protocol.
final class WebHubSocket implements HubSocket {
  WebHubSocket(this._channel) {
    _messages = _channel.stream
        .where((frame) => frame is String)
        .cast<String>()
        .transform(
          StreamTransformer<String, String>.fromHandlers(
            handleError: (error, stack, sink) {
              _open = false;
              sink.addError(error, stack);
            },
            handleDone: (sink) {
              _open = false;
              sink.close();
            },
          ),
        )
        .asBroadcastStream();
  }

  final WebSocketChannel _channel;
  late final Stream<String> _messages;
  var _open = true;

  @override
  Stream<String> get messages => _messages;

  @override
  bool get isOpen => _open;

  @override
  Future<void> send(String text) async {
    if (!_open) throw StateError('hub WebSocket is closed');
    _channel.sink.add(text);
  }

  @override
  Future<void> close() async {
    if (!_open) return;
    _open = false;
    await _channel.sink.close();
  }
}

import 'dart:typed_data';

import 'package:flutter_agent_harness/flutter_agent_harness.dart';

/// The mount segment inside the agent's filesystem: the user-selected
/// project folder (macOS sandbox, user-selected read-write entitlement)
/// appears under this path while the env root stays the app container.
const projectMountSegment = '/project';

/// Maps the `/project` mount segment onto a user-selected host directory,
/// delegating everything else to the app-container env.
///
/// When a project folder is mounted, the agent's working directory becomes
/// `/project` and shell executions run inside the host directory. Sessions
/// (and any other cwd-relative state) are therefore scoped to the mounted
/// folder, matching the CLI behavior where each workspace has its own
/// `sessions/` directory.
///
/// Path mapping is idempotent: host paths already under the mounted
/// directory pass through unchanged, so values the env itself hands out
/// ([absolutePath]/[joinPath] results, [FileInfo.path]) stay valid input.
final class ProjectMountEnv
    implements
        ExecutionEnv,
        BackgroundShell,
        RangedReadFileSystem,
        RenamableFileSystem {
  /// Creates an env over [delegate] with no active mount.
  ProjectMountEnv(this._delegate);

  final ExecutionEnv _delegate;
  String? _mountedRoot;

  /// The currently mounted host directory, or null when nothing is mounted.
  String? get mountedRoot => _mountedRoot;

  /// Mounts [hostPath] (null unmounts). No FS access here — the caller
  /// (store/channel) owns the security-scoped access lifecycle.
  set mountedRoot(String? hostPath) =>
      _mountedRoot = hostPath == null || hostPath.isEmpty ? null : hostPath;

  /// Whether the agent's tools are restricted to operate only inside the
  /// mounted folder. Persists across restarts via [ProjectMountStore.scoped].
  /// The flag is independent of the mount itself — toggling it does not
  /// re-pick the folder; use the workspace dialog to change it.
  bool scoped = false;

  /// A stored mount whose bookmark no longer resolves (folder moved or
  /// deleted): the UI offers to pick again. Set at startup remount only.
  String? mountUnavailable;

  String _map(String path) {
    final root = _mountedRoot;
    if (root == null) return path;
    if (path == projectMountSegment) return root;
    if (path.startsWith('$projectMountSegment/')) {
      return '$root/${path.substring(projectMountSegment.length + 1)}';
    }
    return path;
  }

  @override
  String get cwd => _mountedRoot != null ? projectMountSegment : _delegate.cwd;

  @override
  Future<Result<ShellExecResult, ExecutionError>> exec(
    String command, {
    ShellExecOptions? options,
  }) {
    final root = _mountedRoot;
    if (root == null) return _delegate.exec(command, options: options);
    final optsCwd = options?.cwd;
    final cwd = optsCwd == null ? root : _map(optsCwd);
    final mappedOptions = ShellExecOptions(
      cwd: cwd,
      env: options?.env,
      timeout: options?.timeout,
      cancelToken: options?.cancelToken,
      onStdout: options?.onStdout,
      onStderr: options?.onStderr,
    );
    return _delegate.exec(command, options: mappedOptions);
  }

  // Background shell jobs (desktop: the delegate is the real host shell).
  // The log path comes from the registry under env.cwd — already a host path,
  // so it needs no mount mapping.

  @override
  bool get backgroundJobsSupported {
    final delegate = _delegate;
    if (delegate case final BackgroundShell bg) {
      return bg.backgroundJobsSupported;
    }
    return false;
  }

  @override
  Future<Result<ShellJob, ExecutionError>> startShellJob(
    String command, {
    required String id,
    required String logPath,
    ShellExecOptions? options,
  }) {
    final root = _mountedRoot;
    final mappedOptions = root == null
        ? options
        : ShellExecOptions(
            cwd: options?.cwd == null ? root : _map(options!.cwd!),
            env: options?.env,
            timeout: options?.timeout,
            cancelToken: options?.cancelToken,
            onStdout: options?.onStdout,
            onStderr: options?.onStderr,
            jobLogMaxBytes: options?.jobLogMaxBytes,
            onJobLogWarning: options?.onJobLogWarning,
            stdinData: options?.stdinData,
            liveStdin: options?.liveStdin,
          );
    final delegate = _delegate;
    if (delegate case final BackgroundShell bg) {
      return bg.startShellJob(
        command,
        id: id,
        // Log paths computed from env.cwd may use the virtual /project segment;
        // the delegate (real host shell) needs the physical host path.
        logPath: root == null ? logPath : _map(logPath),
        options: mappedOptions,
      );
    }
    return Future.value(
      const Err(
        ExecutionError(
          ExecutionErrorCode.shellUnavailable,
          'background shell jobs are not supported by this shell',
        ),
      ),
    );
  }

  @override
  Future<Result<String, FileError>> absolutePath(String path) =>
      _delegate.absolutePath(_map(path));

  @override
  Future<Result<String, FileError>> joinPath(List<String> parts) =>
      _delegate.joinPath(parts);

  @override
  Future<Result<String, FileError>> readTextFile(String path) =>
      _delegate.readTextFile(_map(path));

  @override
  Future<Result<Uint8List, FileError>> readBinaryFile(String path) =>
      _delegate.readBinaryFile(_map(path));

  @override
  Future<Result<Uint8List, FileError>> readRange(
    String path,
    int start,
    int end,
  ) {
    final delegate = _delegate;
    if (delegate case final RangedReadFileSystem ranged) {
      return ranged.readRange(_map(path), start, end);
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'readRange not supported by $delegate',
          path: path,
        ),
      ),
    );
  }

  @override
  Future<Result<void, FileError>> renamePath(String from, String to) {
    final delegate = _delegate;
    if (delegate case final RenamableFileSystem renamable) {
      return renamable.renamePath(_map(from), _map(to));
    }
    return Future.value(
      Err(
        FileError(
          FileErrorCode.notSupported,
          'renamePath not supported by $delegate',
          path: from,
        ),
      ),
    );
  }

  @override
  Future<Result<List<String>, FileError>> readTextLines(
    String path, {
    int? maxLines,
  }) => _delegate.readTextLines(_map(path), maxLines: maxLines);

  @override
  Future<Result<void, FileError>> writeBinaryFile(
    String path,
    Uint8List content,
  ) => _delegate.writeBinaryFile(_map(path), content);

  @override
  Future<Result<void, FileError>> writeFile(String path, String content) =>
      _delegate.writeFile(_map(path), content);

  @override
  Future<Result<void, FileError>> appendFile(String path, String content) =>
      _delegate.appendFile(_map(path), content);

  @override
  Future<Result<FileInfo, FileError>> fileInfo(String path) =>
      _delegate.fileInfo(_map(path));

  @override
  Future<Result<List<FileInfo>, FileError>> listDir(String path) =>
      _delegate.listDir(_map(path));

  @override
  Future<Result<bool, FileError>> exists(String path) =>
      _delegate.exists(_map(path));

  @override
  Future<Result<void, FileError>> createDir(
    String path, {
    bool recursive = true,
  }) => _delegate.createDir(_map(path), recursive: recursive);

  @override
  Future<Result<void, FileError>> remove(
    String path, {
    bool recursive = false,
    bool force = false,
  }) => _delegate.remove(_map(path), recursive: recursive, force: force);
}

/// The directory used for session scoping.
///
/// When a project folder is mounted this is the host path, so sessions and
/// messaging are stored at the same physical location as the CLI uses for the
/// same workspace. Otherwise it falls back to [ExecutionEnv.cwd].
extension SessionCwd on ExecutionEnv {
  String get sessionCwd {
    var env = this;
    // Unwrap decorators (secrets/session-vars) that sit between callers
    // and the mount env so the mounted host path is found reliably.
    while (true) {
      if (env is SecretsExecutionEnv) {
        env = env.delegate;
      } else if (env is SessionVarsExecutionEnv) {
        env = env.delegate;
      } else {
        break;
      }
    }
    if (env case final ProjectMountEnv mountEnv) {
      final root = mountEnv.mountedRoot;
      if (root != null) return root;
    }
    return cwd;
  }
}

/// App-container storage root, never the mounted user project. Dedicated
/// credentials and identities must not become project/session artifacts.
extension AppStorageCwd on ExecutionEnv {
  String get appStorageCwd {
    var env = this;
    while (true) {
      if (env is SecretsExecutionEnv) {
        env = env.delegate;
      } else if (env is SessionVarsExecutionEnv) {
        env = env.delegate;
      } else if (env case final ProjectMountEnv mountEnv) {
        env = mountEnv._delegate;
      } else {
        return env.cwd;
      }
    }
  }
}

/// The injectable WebSocket seam for the hub-backed messaging fabric
/// (issue #402, phase 27.1): the pure-Dart [HubMessagingRepository] dials
/// the hub through this interface — the same seam as the LSP/MCP clients.
///
/// `lib/io.dart` supplies the real `dart:io` WebSocket binding
/// (`IoHubTransport`); tests inject an in-memory fake. Nothing in
/// `lib/src/messaging/` touches sockets directly.
library;

/// One live hub connection.
abstract interface class HubSocket {
  /// Inbound text frames. The stream completing (done or error) means the
  /// connection is gone — the repository reconnects through its transport.
  Stream<String> get messages;

  /// Whether the connection can still accept outbound frames.
  bool get isOpen;

  /// Writes one text frame.
  Future<void> send(String text);

  /// Closes the connection; idempotent.
  Future<void> close();
}

/// Dials a hub URL (`ws://host:port/ws`) — the only network operation the
/// hub fabric performs. Implementations throw when the hub is unreachable
/// or rejects the upgrade (wrong pairing token); the repository treats any
/// throw as "not connected" and retries with backoff.
abstract interface class HubTransport {
  Future<HubSocket> connect(Uri url);
}

/// Optional authentication capability for a [HubTransport].
///
/// Native transports send the enrollment secret in the WebSocket
/// authorization header. Browser transports use [hubUrlWithBrowserBearer],
/// the hub's equivalent `?token=` upgrade credential. Transports without
/// this capability can still serve open/token-paired hubs through
/// [HubTransport.connect].
abstract interface class HubBearerTransport {
  /// Dials [url] with the enrollment secret as bearer-equivalent auth.
  Future<HubSocket> connectWithBearer(Uri url, String secret);
}

/// The browser bearer equivalent: `?token=<url-encoded secret>`.
///
/// Browser WebSocket cannot set an Authorization header. Keep the protocol's
/// query-parameter name isolated here so every browser host uses the same
/// authentication path. The returned URI contains a credential: never log it
/// or include it in an exception.
Uri hubUrlWithBrowserBearer(Uri url, String secret) =>
    url.replace(queryParameters: {...url.queryParameters, 'token': secret});

/// `dart:io`-backed bindings for the hub messaging fabric (issue #402,
/// phase 27.1): the WebSocket [HubTransport] and a file-backed identity
/// store, so the app agent keeps the same hub address across restarts.
///
/// **This library is not web-safe.** It is exported only from
/// `lib/io.dart`; the pure core (`hub_messaging_repository.dart`) never
/// imports it — hosts inject a transport through the [HubTransport] seam.
library;

import 'dart:io';
import 'dart:math';

import 'hub_identity.dart';
import 'hub_transport.dart';

/// A [HubTransport] over a `dart:io` WebSocket.
final class IoHubTransport implements HubTransport, HubBearerTransport {
  const IoHubTransport();

  @override
  Future<HubSocket> connect(Uri url) => _connect(url);

  @override
  Future<HubSocket> connectWithBearer(Uri url, String secret) =>
      _connect(url, headers: {'Authorization': 'Bearer $secret'});

  Future<HubSocket> _connect(Uri url, {Map<String, String>? headers}) async {
    final ws = await WebSocket.connect(url.toString(), headers: headers);
    return IoHubSocket(ws);
  }
}

/// One live hub connection over a `dart:io` WebSocket. Binary frames are
/// dropped at the boundary (the hub speaks text frames only and answers
/// them with a `bad_frame` error).
final class IoHubSocket implements HubSocket {
  IoHubSocket(this._ws);

  final WebSocket _ws;

  @override
  Stream<String> get messages =>
      _ws.where((frame) => frame is String).cast<String>().asBroadcastStream();

  @override
  bool get isOpen => _ws.readyState == WebSocket.open;

  @override
  Future<void> send(String text) async {
    _ws.add(text);
  }

  @override
  Future<void> close() => _ws.close();
}

/// Loads the hub identity persisted at [path], creating it (mode 0600,
/// atomic temp+rename) on first use. File format — the SAME lines the
/// CLI's `fa_hub_client` key files use — so a host may share one identity
/// across surfaces when it wants to:
/// `ed25519:<seed b64>`, `x25519:<priv b64>`, `x25519pub:<pub b64>`.
/// The pub line is informational; keys are always re-derived from the
/// private scalars, so a torn legacy write can never pair a mismatched pub.
Future<HubIdentity> loadHubIdentity(String path) async {
  final file = File(path);
  if (await file.exists()) {
    try {
      return await hubIdentityFromKeyFile(await file.readAsString());
    } on Object {
      // A torn or corrupt file falls through to regeneration: a fresh
      // address beats an unusable fabric; save overwrites the file.
    }
  }
  final identity = await HubIdentity.fromSeeds(
    ed25519Seed: _randomBytes(32),
    x25519Private: _randomBytes(32),
  );
  await File(path).parent.create(recursive: true);
  // Atomic create via temp + rename: a crashed direct write could tear the
  // file mid-line and break every later load.
  final tmp = File('$path.tmp');
  await tmp.writeAsString(await hubIdentityToKeyFile(identity), flush: true);
  await tmp.rename(path);
  if (!await _chmod600(path)) {
    stderr.writeln(
      '[hub] warning: identity file $path was NOT locked to mode 0600 — '
      'the private keys may be readable by other local users',
    );
  }
  return identity;
}

Future<bool> _chmod600(String path) async {
  if (Platform.isWindows) return false;
  try {
    final result = await Process.run('chmod', ['600', path]);
    return result.exitCode == 0;
  } on Object {
    return false;
  }
}

final _random = Random.secure();

List<int> _randomBytes(int count) =>
    List<int>.generate(count, (_) => _random.nextInt(256));

/// Saves [identity]'s seeds to [path] (the host's rotation/rebind path).
Future<void> saveHubIdentity(String path, HubIdentity identity) async {
  await File(path).parent.create(recursive: true);
  await File(
    path,
  ).writeAsString(await hubIdentityToKeyFile(identity), flush: true);
  await _chmod600(path);
}

/// DAP/1 agent identity for the hub-backed messaging fabric: an Ed25519
/// signing keypair plus a separate X25519 keypair for payload E2E (no
/// cross-algorithm key reuse) — `agentId = hex(sha256(ed25519_pubkey))[:16]`
/// per docs/protocol.md.
///
/// Pure Dart (the crypto comes from `package:cryptography`): generates and
/// holds keys, never touches files. Persistence is a host concern — the io
/// entry point (`lib/io.dart`) binds a file-backed loader so the app agent
/// keeps the same id across restarts (stable names/addressing).
library;

import 'dart:convert';
import 'dart:math';

import 'package:cryptography/cryptography.dart';

final _ed25519 = Ed25519();
final _x25519 = X25519();
final _sha256 = Sha256();
final _random = Random.secure();

/// Random lowercase hex string of [nChars] characters (hello nonces).
String hubRandomHex(int nChars) =>
    List.generate(nChars, (_) => _random.nextInt(16).toRadixString(16)).join();

/// Opaque unique frame id, uuid-v4 shaped.
String newHubFrameId() {
  final b = List<int>.generate(16, (_) => _random.nextInt(256));
  b[6] = (b[6] & 0x0f) | 0x40;
  b[8] = (b[8] & 0x3f) | 0x80;
  final h = b.map((v) => v.toRadixString(16).padLeft(2, '0')).join();
  return '${h.substring(0, 8)}-${h.substring(8, 12)}-${h.substring(12, 16)}-'
      '${h.substring(16, 20)}-${h.substring(20)}';
}

/// The hex-encoding shared by id derivation and signing payloads.
String hubHex(List<int> bytes) =>
    bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join();

/// The DAP/1 agent identity (signing + DH keypairs, derived agent id).
final class HubIdentity {
  HubIdentity._({
    required this.signingKeyPair,
    required this.signingPublicKey,
    required this.dhKeyPair,
    required this.dhPublicKey,
    required this.agentId,
  });

  final SimpleKeyPair signingKeyPair;
  final SimplePublicKey signingPublicKey;

  /// X25519 keypair used for payload encryption (never for signatures).
  final SimpleKeyPair dhKeyPair;
  final SimplePublicKey dhPublicKey;

  /// `hex(sha256(ed25519_pubkey_raw))[:16]` — the hub address.
  final String agentId;

  String get signingPubkeyB64 => base64Encode(signingPublicKey.bytes);
  String get dhPubkeyB64 => base64Encode(dhPublicKey.bytes);

  /// Generates a fresh identity (tests, first boot without a store).
  static Future<HubIdentity> generate() async => _build(
    signingKeyPair: await _ed25519.newKeyPair(),
    dhKeyPair: await _x25519.newKeyPair(),
  );

  /// Rebuilds an identity from persisted seeds — the stable-address path
  /// (hosts store the seeds, the id survives restarts).
  static Future<HubIdentity> fromSeeds({
    required List<int> ed25519Seed,
    required List<int> x25519Private,
  }) async => _build(
    signingKeyPair: await _ed25519.newKeyPairFromSeed(ed25519Seed),
    dhKeyPair: await _x25519.newKeyPairFromSeed(x25519Private),
  );

  static Future<HubIdentity> _build({
    required SimpleKeyPair signingKeyPair,
    required SimpleKeyPair dhKeyPair,
  }) async {
    final signingPub = await signingKeyPair.extractPublicKey();
    final dhPub = await dhKeyPair.extractPublicKey();
    final digest = await _sha256.hash(signingPub.bytes);
    return HubIdentity._(
      signingKeyPair: signingKeyPair,
      signingPublicKey: signingPub,
      dhKeyPair: dhKeyPair,
      dhPublicKey: dhPub,
      agentId: hubHex(digest.bytes).substring(0, 16),
    );
  }
}

/// Serializes [identity] in the CLI-compatible hub key-file format.
///
/// This pure-Dart boundary is shared by file and browser [ExecutionEnv]-style
/// stores; persistence and its durability guarantees remain host concerns.
Future<String> hubIdentityToKeyFile(HubIdentity identity) async {
  final signingSeed = await identity.signingKeyPair.extractPrivateKeyBytes();
  final dhPriv = await identity.dhKeyPair.extractPrivateKeyBytes();
  return 'ed25519:${base64Encode(signingSeed)}\n'
      'x25519:${base64Encode(dhPriv)}\n'
      'x25519pub:${identity.dhPubkeyB64}\n';
}

/// Restores an identity from [hubIdentityToKeyFile] output (or a CLI key
/// file). The informational public-key line is never trusted: both public
/// keys and the agent id are re-derived from the private scalars.
Future<HubIdentity> hubIdentityFromKeyFile(String contents) async {
  final fields = <String, String>{};
  for (final line in contents.split('\n')) {
    final idx = line.indexOf(':');
    if (idx > 0) fields[line.substring(0, idx)] = line.substring(idx + 1);
  }
  final seed = fields['ed25519'];
  final dhPriv = fields['x25519'];
  if (seed == null || dhPriv == null) {
    throw const FormatException('hub identity is missing private keys');
  }
  return HubIdentity.fromSeeds(
    ed25519Seed: base64Decode(seed),
    x25519Private: base64Decode(dhPriv),
  );
}

/// DAP/1 client transport for the browser: WebSocket via js_interop (the
/// extension SW has no dart:io), one connect cycle, E2E DM crypto over
/// fa_hub_client's pure functions, and backoff reconnects. Failures are
/// quiet by contract — nothing here throws into the host loop.
///
/// Cycle: connect → hello → welcome (agentId assigned) → rejoin the enrolled
/// channel and auto-flush the offline mailbox. Public and invited keyed
/// channels use the same runtime as ordinary hub presence.
library;

import 'dart:async';
import 'dart:convert';
import 'dart:js_interop';

import 'package:fa_hub_client/src/hub/canonical.dart';

import 'dap_frames.dart';

/// Connection phases surfaced as status events.
enum DapPhase {
  connecting,
  connected,
  reconnecting,
  disconnected,

  /// The hub is up but rejecting the credential (likely a wrong
  /// Hub password): fast retries are held at a slow re-check.
  unauthorized,
}

/// One status snapshot (panel shows `hub: connected as <agentId>` etc.).
final class DapStatus {
  DapStatus({
    required this.phase,
    this.agentId,
    this.reason,
    this.channels = const [],
    this.joinFailed = false,
  });

  final DapPhase phase;
  final String? agentId;
  final String? reason;
  final List<String> channels;
  final bool joinFailed;

  Map<String, dynamic> toMap() => {
    'phase': phase.name,
    if (agentId != null) 'agentId': agentId,
    if (reason != null) 'reason': reason,
    if (channels.isNotEmpty) 'channels': channels,
    if (joinFailed) 'joinFailed': true,
  };
}

// -- Browser WebSocket bindings (MV3 service worker global) ------------------

@JS('WebSocket')
extension type _WebSocket._(JSObject _) implements JSObject {
  external _WebSocket(String url);

  external void send(String data);

  external void close([int? code, String? reason]);

  /// `WebSocket.OPEN`.
  external int get readyState;

  external set onopen(JSFunction? f);

  external set onmessage(JSFunction? f);

  external set onclose(JSFunction? f);

  external set onerror(JSFunction? f);
}

@JS('MessageEvent')
extension type _MessageEvent._(JSObject _) implements JSObject {
  external JSAny? get data;
}

@JS('CloseEvent')
extension type _CloseEvent._(JSObject _) implements JSObject {
  external String get reason;
}

const _wsOpen = 1;
const _lookupTimeout = Duration(seconds: 10);

/// One live DAP/1 connection with reconnect. Create, then [start].
final class DapClient {
  DapClient({
    required this.identity,
    required this.url,
    required this.name,
    required this.onMail,
    required this.onStatus,
    this.secret = '',
    this.clientSecret = '',
    this.channel = '',
    this.channelPub,
    this.channelPriv,
  });

  final DapIdentity identity;
  final String url;

  /// The hub password — appended to the WS URL as the `dap_token` query
  /// param (browser WebSocket cannot set headers; the hub accepts the
  /// query form). Empty = open hub. Never logged.
  final String secret;

  /// Hub-issued enrollment credential (`?token=`). Never logged.
  final String clientSecret;

  /// Enrolled channel and its optional imported keypair. Empty channel =
  /// ordinary hub presence; null keypair = keyless PUBLIC channel.
  final String channel;
  final String? channelPub;
  final String? channelPriv;

  /// Display name advertised in the hello (cosmetic, unique per hub).
  final String name;

  /// Decrypted inbound mail (or the undecryptable placeholder — never
  /// dropped).
  final void Function(String from, String text) onMail;
  final void Function(DapStatus status) onStatus;

  _WebSocket? _ws;
  var _generation = 0;
  var _attempt = 0;
  var _stopped = false;
  var _fatal = false; // hub rejected the hello — stop retrying (§3.1)
  DateTime? _dialAt;
  var _fastCloseStreak = 0;
  var _awaitingWelcome = false;
  String? agentId;
  DapPhase _phase = DapPhase.disconnected;
  String? _reason;
  Timer? _retry;
  final _joinedChannels = <String>{};
  var _joinPending = false;
  var _joinFailed = false;

  /// Peer agentId → advertised x25519 key (whois/presence cache).
  final _peers = <String, String>{};
  final _whoisWaiters = <String, Completer<String?>>{};
  final _presenceWaiters = <String, Completer<List<Map<String, dynamic>>>>{};

  void start() {
    _stopped = false;
    _fatal = false;
    _connect();
  }

  Future<void> stop() async {
    _stopped = true;
    _generation++;
    _retry?.cancel();
    final ws = _ws;
    _ws = null;
    _joinedChannels.clear();
    _joinPending = false;
    ws?.close();
    _set(DapPhase.disconnected, reason: 'stopped');
  }

  /// Sends an E2E DM. [to] is a 16-hex agent id or a unique online display
  /// name. Throws a descriptive error (the tool loop surfaces it); never
  /// throws for transport reasons — those stay quiet in the status.
  Future<String> sendDm(String to, String text) async {
    if (_phase != DapPhase.connected || _ws == null) {
      throw StateError('not connected to the hub');
    }
    final target = to.trim();
    final (peerId, peerX) = RegExp(r'^[0-9a-f]{16}$').hasMatch(target)
        ? await _byId(target)
        : await _byName(target);
    final frameId = newFrameId();
    final ciphertext = await encryptDm(identity, peerX, frameId, peerId, text);
    _send(
      jsonEncode(
        await sendFrame(
          from: identity,
          to: peerId,
          ciphertext: ciphertext,
          frameId: frameId,
        ),
      ),
    );
    return 'sent to $peerId';
  }

  /// Presence roster (every agent ever seen by the hub, self included).
  /// Empty list on timeout — presence is best-effort.
  Future<List<Map<String, dynamic>>> presence() async {
    if (_phase != DapPhase.connected || _ws == null) {
      throw StateError('not connected to the hub');
    }
    final frameId = newFrameId();
    final waiter = Completer<List<Map<String, dynamic>>>();
    _presenceWaiters[frameId] = waiter;
    _send(jsonEncode(presenceQueryFrame(frameId)));
    try {
      return await waiter.future.timeout(
        _lookupTimeout,
        onTimeout: () => const [],
      );
    } finally {
      _presenceWaiters.remove(frameId);
    }
  }

  Future<(String, String)> _byId(String agentId) async {
    final x = await _whoisKey(agentId);
    if (x == null) throw StateError('unknown agent $agentId on the hub');
    return (agentId, x);
  }

  Future<(String, String)> _byName(String name) async {
    final matches = <(String, String)>[
      for (final agent in await presence())
        if (agent['online'] == true && agent['name'] == name)
          (agent['agentId'] as String, agent['x25519'] as String? ?? ''),
    ];
    if (matches.isEmpty) {
      throw StateError(
        'no online agent named "$name" (dap_peers lists who is)',
      );
    }
    if (matches.length > 1) {
      throw StateError('"$name" is ambiguous — use the 16-hex id');
    }
    final (id, x) = matches.single;
    if (x.isEmpty) throw StateError('agent $id advertises no x25519 key');
    _peers[id] = x;
    return (id, x);
  }

  /// The credential-bearing URL actually dialed. Never log it: it can carry
  /// both the legacy hub password and the enrollment bearer equivalent.
  String get wsUrl => dapWsUrlWithEnrollmentSecret(
    dapWsUrlWithToken(url, secret),
    clientSecret,
  );

  // -- Connection cycle -------------------------------------------------------

  void _connect() {
    if (_stopped || _fatal) return;
    final gen = ++_generation;
    _dialAt = DateTime.now();
    print('[dap] ws dial (attempt ${_attempt + 1})');
    final ws = _WebSocket(wsUrl);
    _ws = ws;
    _awaitingWelcome = true;
    if (_attempt == 0) _set(DapPhase.connecting);

    void onOpen() {
      print('[dap] ws open — sending hello');
      if (gen == _generation) unawaited(_sendHello());
    }

    void onMessage(JSObject event) {
      if (gen == _generation) {
        unawaited(_handleRaw((event as _MessageEvent).data));
      }
    }

    void onClose(JSObject event) {
      if (gen != _generation || _stopped || _fatal) return;
      _ws = null;
      _awaitingWelcome = false;
      _attempt++;
      var reason = '';
      try {
        reason = (event as _CloseEvent).reason;
      } on Object {
        // Non-CloseEvent close — fall through with an empty reason.
      }
      // A rejecting peer can echo the credentialed upgrade URI in its close
      // reason. Authenticated connections never log or propagate that text.
      final safeReason = secret.isEmpty && clientSecret.isEmpty ? reason : '';
      if (_joinPending) _joinFailed = true;
      _joinPending = false;
      _joinedChannels.clear();
      print(
        '[dap] ws closed'
        '${safeReason.isEmpty ? '' : ' ($safeReason)'} — retry #$_attempt',
      );
      final dialAt = _dialAt;
      final fast =
          dialAt != null && DateTime.now().difference(dialAt) < fastCloseWindow;
      _fastCloseStreak = fast ? _fastCloseStreak + 1 : 0;
      if (looksLikeCredentialRejection(
        _fastCloseStreak,
        hasCredential: secret.isNotEmpty || clientSecret.isNotEmpty,
      )) {
        if (_fastCloseStreak == 3) {
          print(
            '[dap] the hub keeps rejecting the credential — holding at a '
            '${credentialRecheckInterval.inSeconds}s re-check (save or '
            'rejoin with a new credential)',
          );
        }
        _set(DapPhase.unauthorized, reason: safeReason);
        _retry?.cancel();
        _retry = Timer(credentialRecheckInterval, _connect);
        return;
      }
      _set(DapPhase.reconnecting, reason: safeReason);
      _retry?.cancel();
      _retry = Timer(reconnectBackoff(_attempt), _connect);
    }

    ws.onopen = onOpen.toJS;
    ws.onmessage = onMessage.toJS;
    ws.onclose = onClose.toJS;
    ws.onerror = (() {}).toJS; // close always follows; status covers it
  }

  Future<void> _sendHello() async {
    try {
      _send(
        jsonEncode(
          await helloFrame(identity, name: name.isEmpty ? null : name),
        ),
      );
    } on Object {
      // Signing should never fail; force the retry path regardless.
      _ws?.close();
    }
  }

  Future<void> _handleRaw(JSAny? data) async {
    try {
      final frame = (jsonDecode((data as JSString).toDart) as Map)
          .cast<String, dynamic>();
      await _onFrame(frame);
    } on Object {
      // Malformed frame — ignore; the connection stays up.
    }
  }

  Future<void> _onFrame(Map<String, dynamic> frame) async {
    switch (frame['op']) {
      case 'welcome':
        _awaitingWelcome = false;
        _attempt = 0;
        _fastCloseStreak = 0;
        _dialAt = null;
        agentId = frame['agentId'] as String? ?? agentId;
        print('[dap] welcome — online as $agentId');
        _joinedChannels.clear();
        _joinFailed = false;
        _set(DapPhase.connected);
        await _joinEnrolledChannel();
        _send(jsonEncode(flushFrame())); // drain offline mail
      case 'msg':
        await _onMsg(frame);
      case 'agent_info':
        final id = frame['agentId'] as String?;
        final x = frame['x25519'] as String?;
        if (id != null && x != null && x.isNotEmpty) _peers[id] = x;
        _whoisWaiters.remove(id)?.complete(x);
      case 'presence':
        final agents = [
          for (final entry in (frame['agents'] as List? ?? const []))
            (entry as Map).cast<String, dynamic>(),
        ];
        for (final agent in agents) {
          final id = agent['agentId'] as String?;
          final x = agent['x25519'] as String?;
          if (id != null && x != null && x.isNotEmpty) _peers[id] = x;
        }
        _presenceWaiters.remove(frame['replyTo'] as String?)?.complete(agents);
      case 'flushed':
        break; // delivered mail already arrived as msg frames
      case 'joined':
        final joined = frame['channel'] as String? ?? '';
        if (joined.isNotEmpty && joined == channel) {
          _joinedChannels.add(joined);
          _joinPending = false;
          _joinFailed = false;
          _notify();
        }
      case 'error':
        final code = frame['code'] as String? ?? 'error';
        final safeCode = clientSecret.isEmpty ? code : 'error';
        if (_awaitingWelcome) {
          // Rejected hello is fatal (§3.1): surface it and stop retrying.
          print('[dap] hub rejected hello: $safeCode — stopped');
          _fatal = true;
          _generation++;
          _ws?.close();
          _ws = null;
          _retry?.cancel();
          _set(DapPhase.disconnected, reason: 'hub rejected hello: $safeCode');
        } else {
          if (_joinPending) {
            _joinPending = false;
            _joinFailed = true;
            _notify();
          }
          // Hub errors carry no target id — fail every pending peer lookup
          // so sendDm reports instead of hanging to the timeout.
          for (final waiter in _whoisWaiters.values) {
            if (!waiter.isCompleted) waiter.complete(null);
          }
          _whoisWaiters.clear();
        }
      default:
        break;
    }
  }

  Future<void> _joinEnrolledChannel() async {
    if (channel.isEmpty || _ws == null) return;
    _joinPending = true;
    try {
      _send(
        jsonEncode(
          await joinFrame(
            identity: identity,
            channel: channel,
            chanPubkey: channelPub ?? '',
          ),
        ),
      );
    } on Object {
      _joinPending = false;
      _joinFailed = true;
      _notify();
    }
  }

  Future<void> _onMsg(Map<String, dynamic> frame) async {
    final from = frame['from'] as String? ?? 'unknown';
    final channelName = frame['channel'] as String?;
    if (channelName != null) {
      if (channelName != channel || from == agentId) return;
      String? channelText;
      try {
        final pub = channelPub;
        final priv = channelPriv;
        if (pub == null && priv == null) {
          channelText = decodeDapPublicChannelPayload(
            frame['ciphertext'] as String? ?? '',
          );
        } else {
          if (pub == null || priv == null) {
            throw StateError('incomplete channel keypair');
          }
          final senderX = await _whoisKey(from);
          if (senderX == null) throw StateError('no sender DH key');
          channelText = await decryptDapChannelPayload(
            channelPub: pub,
            channelPriv: priv,
            senderX25519B64: senderX,
            frameId: frame['id'] as String? ?? '',
            channel: channelName,
            ciphertextB64: frame['ciphertext'] as String? ?? '',
          );
        }
      } on Object {
        // Never print parser/decryption errors: they can contain key material.
        channelText = null;
      }
      onMail(from, '[#$channelName] ${channelText ?? undecryptableText(from)}');
      return;
    }
    String? text;
    try {
      final senderX = await _whoisKey(from);
      if (senderX != null) {
        text = await decryptDm(
          identity,
          senderX,
          frame['id'] as String? ?? '',
          frame['ciphertext'] as String? ?? '',
        );
      }
    } on Object {
      text = null; // wrong key, tampered box, missing fields
    }
    onMail(from, text ?? undecryptableText(from));
  }

  Future<String?> _whoisKey(String agentId) {
    final cached = _peers[agentId];
    if (cached != null) return Future.value(cached);
    final waiter = Completer<String?>();
    _whoisWaiters[agentId] = waiter;
    _send(jsonEncode(whoisFrame(agentId)));
    return waiter.future
        .timeout(_lookupTimeout, onTimeout: () => null)
        .whenComplete(() {
          if (identical(_whoisWaiters[agentId], waiter)) {
            _whoisWaiters.remove(agentId);
          }
        });
  }

  void _send(String text) {
    final ws = _ws;
    if (ws != null && ws.readyState == _wsOpen) ws.send(text);
  }

  void _set(DapPhase phase, {String? reason}) {
    if (phase == _phase && reason == _reason) return;
    _phase = phase;
    _reason = reason;
    _notify();
  }

  void _notify() => onStatus(
    DapStatus(
      phase: _phase,
      agentId: agentId,
      reason: _reason,
      channels: List<String>.unmodifiable(_joinedChannels),
      joinFailed: _joinFailed,
    ),
  );
}

/// Pure DAP/1 pieces, VM-testable (no js_interop, no dart:io):
/// identity keypairs + the key-file format, frame builders, DM payload
/// encrypt/decrypt wrappers, reconnect backoff, and the shared mail
/// deduper. Crypto primitives come from fa_hub_client's pure slice —
/// nothing is re-implemented here (docs/dap.md is the wire spec).
library;

import 'dart:convert';

import 'package:cryptography/cryptography.dart';
import 'package:fa_hub_client/src/hub/canonical.dart';
import 'package:fa_hub_client/src/hub/payload_crypto.dart';
import 'package:flutter_agent_harness/src/messaging/hub_transport.dart'
    show hubUrlWithBrowserBearer;

/// DAP/1 identity: an Ed25519 signing keypair plus a separate X25519
/// keypair for payload E2E (no cross-algorithm key reuse).
///
/// `agentId = hex(sha256(ed25519_pubkey_raw))[:16]` — same key, same id on
/// every hub. Serialized in the `~/.dap` key-file format so an exported
/// identity is byte-compatible with the CLI's (`ed25519:<seed b64>`,
/// `x25519:<priv b64>`, `x25519pub:<pub b64>` — that last line is
/// informational; the public key is always re-derived from the scalar).
/// The WS URL a browser client actually dials: [url] plus the
/// `dap_token` credential when a hub password is set (browser WebSocket
/// cannot set headers; the hub accepts the query form on the upgrade).
/// Never log the result — log [url] instead.
String dapWsUrlWithToken(String url, String secret) {
  if (secret.isEmpty) return url;
  final uri = Uri.parse(url);
  return uri
      .replace(queryParameters: {...uri.queryParameters, 'dap_token': secret})
      .toString();
}

/// The enrollment secret uses the same bearer-equivalent `?token=` upgrade
/// auth as the plain-web app. The returned URL is credential-bearing and
/// must never be logged or included in an exception.
String dapWsUrlWithEnrollmentSecret(String url, String secret) {
  if (secret.isEmpty) return url;
  return hubUrlWithBrowserBearer(Uri.parse(url), secret).toString();
}

final class DapIdentity {
  DapIdentity._({
    required this.signingKeyPair,
    required this.signingPublicKey,
    required this.dhKeyPair,
    required this.dhPublicKey,
    required this.agentId,
  });

  final SimpleKeyPair signingKeyPair;
  final SimplePublicKey signingPublicKey;

  /// X25519 keypair used for payload encryption (never for signatures).
  final SimpleKeyPair dhKeyPair;
  final SimplePublicKey dhPublicKey;

  /// `hex(sha256(ed25519_pubkey_raw))[:16]`.
  final String agentId;

  String get signingPubkeyB64 => base64Encode(signingPublicKey.bytes);
  String get dhPubkeyB64 => base64Encode(dhPublicKey.bytes);

  static Future<DapIdentity> generate() async => _build(
    signingKeyPair: await Ed25519().newKeyPair(),
    dhKeyPair: await X25519().newKeyPair(),
  );

  /// Restores an identity from [toKeyFile] output (or a CLI-written key
  /// file). Never trusts the stored `x25519pub:` line — the public key is
  /// re-derived from the private scalar.
  static Future<DapIdentity> fromKeyFile(String contents) async {
    final fields = <String, String>{};
    for (final line in contents.split('\n')) {
      final idx = line.indexOf(':');
      if (idx > 0) fields[line.substring(0, idx)] = line.substring(idx + 1);
    }
    final seed = fields['ed25519'];
    final dhPriv = fields['x25519'];
    if (seed == null || dhPriv == null) {
      throw ArgumentError('key file missing ed25519:/x25519: lines');
    }
    return _build(
      signingKeyPair: await Ed25519().newKeyPairFromSeed(base64Decode(seed)),
      dhKeyPair: await X25519().newKeyPairFromSeed(base64Decode(dhPriv)),
    );
  }

  static Future<DapIdentity> _build({
    required SimpleKeyPair signingKeyPair,
    required SimpleKeyPair dhKeyPair,
  }) async {
    final signingPub = await signingKeyPair.extractPublicKey();
    final dhPub = await dhKeyPair.extractPublicKey();
    final digest = await Sha256().hash(signingPub.bytes);
    return DapIdentity._(
      signingKeyPair: signingKeyPair,
      signingPublicKey: signingPub,
      dhKeyPair: dhKeyPair,
      dhPublicKey: dhPub,
      agentId: hexEncode(digest.bytes).substring(0, 16),
    );
  }

  /// Key-file serialization (see [fromKeyFile]).
  Future<String> toKeyFile() async {
    final seed = await signingKeyPair.extractPrivateKeyBytes();
    final dhPriv = await dhKeyPair.extractPrivateKeyBytes();
    return 'ed25519:${base64Encode(seed)}\n'
        'x25519:${base64Encode(dhPriv)}\n'
        'x25519pub:$dhPubkeyB64\n';
  }
}

/// Signed `hello` frame (docs/dap.md §3.1): fresh ts, ≥16-char random hex
/// nonce, signature over the frame without `sig`.
Future<Map<String, dynamic>> helloFrame(
  DapIdentity identity, {
  String? name,
  DateTime? now,
}) async {
  final frame = <String, dynamic>{
    'op': 'hello',
    'v': 1,
    'pubkey': identity.signingPubkeyB64,
    'x25519': identity.dhPubkeyB64,
    'nonce': randomHex(16),
    'ts': (now ?? DateTime.now()).millisecondsSinceEpoch,
    if (name != null && name.isNotEmpty) 'name': name,
  };
  frame['sig'] = await signFrame(frame, identity.signingKeyPair);
  return frame;
}

/// Signed `send` frame carrying an already-encrypted DM payload.
Future<Map<String, dynamic>> sendFrame({
  required DapIdentity from,
  required String to,
  required String ciphertext,
  String? frameId,
  int? ts,
}) async {
  final frame = <String, dynamic>{
    'op': 'send',
    'to': to,
    'id': frameId ?? newFrameId(),
    'ts': ts ?? DateTime.now().millisecondsSinceEpoch,
    'ciphertext': ciphertext,
  };
  frame['sig'] = await signFrame(frame, from.signingKeyPair);
  return frame;
}

/// Unsigned `whois` request — the hub never verifies these.
Map<String, dynamic> whoisFrame(String agentId) => {
  'op': 'whois',
  'agentId': agentId,
};

/// Unsigned `presence_query`. The hub echoes [frameId] back as `replyTo`,
/// letting the client match answers to waiters.
Map<String, dynamic> presenceQueryFrame(String frameId) => {
  'op': 'presence_query',
  'id': frameId,
};

/// Unsigned `flush` — drains the hub-side offline mailbox.
Map<String, dynamic> flushFrame() => {'op': 'flush'};

/// Signed `join`. Public enrollment passes an empty [chanPubkey]; an invited
/// private channel passes its imported public key (the private key stays
/// local for payload decryption).
Future<Map<String, dynamic>> joinFrame({
  required DapIdentity identity,
  required String channel,
  required String chanPubkey,
}) async {
  final frame = <String, dynamic>{
    'op': 'join',
    'channel': channel,
    'chanPubkey': chanPubkey,
  };
  frame['sig'] = await signFrame(frame, identity.signingKeyPair);
  return frame;
}

/// PUBLIC channel payload: base64(JSON text), with base64 raw UTF-8 tolerated
/// for foreign producers. Keyed channels never take this path.
String decodeDapPublicChannelPayload(String payloadB64) {
  final raw = utf8.decode(base64Decode(payloadB64));
  try {
    final decoded = jsonDecode(raw);
    if (decoded is Map && decoded['text'] is String) {
      return decoded['text'] as String;
    }
  } on Object {
    // Raw UTF-8 from a foreign producer.
  }
  return raw;
}

/// Decrypts keyed-channel mail with the invited channel private key and the
/// sender's advertised DH public key.
Future<String> decryptDapChannelPayload({
  required String channelPub,
  required String channelPriv,
  required String senderX25519B64,
  required String frameId,
  required String channel,
  required String ciphertextB64,
}) {
  return decryptPayload(
    recipientDhKeyPair: SimpleKeyPairData(
      base64Decode(channelPriv),
      publicKey: SimplePublicKey(
        base64Decode(channelPub),
        type: KeyPairType.x25519,
      ),
      type: KeyPairType.x25519,
    ),
    senderDhPubkey: SimplePublicKey(
      base64Decode(senderX25519B64),
      type: KeyPairType.x25519,
    ),
    frameId: frameId,
    aadTarget: channel,
    ciphertextB64: ciphertextB64,
  );
}

/// Encrypts a DM payload for the holder of [peerX25519B64]. [to] (the
/// recipient agentId) is the AAD target, binding the payload to its route.
Future<String> encryptDm(
  DapIdentity from,
  String peerX25519B64,
  String frameId,
  String to,
  String plaintext,
) {
  return encryptPayload(
    senderDhKeyPair: from.dhKeyPair,
    recipientDhPubkey: SimplePublicKey(
      base64Decode(peerX25519B64),
      type: KeyPairType.x25519,
    ),
    frameId: frameId,
    aadTarget: to,
    plaintext: plaintext,
  );
}

/// Reconnect backoff (docs/dap.md): 1 s doubling, capped at 30 s. The cap
/// is clamped BEFORE the shift so far-out attempts can never overflow.
Duration reconnectBackoff(int attempt) {
  final shift = attempt.clamp(1, 6) - 1; // clamp before shift (cap 30 s)
  return Duration(seconds: 1 << shift > 30 ? 30 : 1 << shift);
}

/// The credential-rejection hold: when a Hub password IS configured and
/// [fastCloseStreak] consecutive dials all closed within
/// [fastCloseWindow] — the browser WebSocket exposes no HTTP status, so
/// a 401 is inferred — stop the fast retry loop (a wrong password never
/// fixes itself) and hold at a slow [credentialRecheckInterval] re-check
/// so a hub that later comes up (or a re-saved password) still heals.
bool looksLikeCredentialRejection(
  int fastCloseStreak, {
  required bool hasCredential,
}) => hasCredential && fastCloseStreak >= 3;

/// A dial that closed within this window counts as a fast close (the hub
/// answered and rejected, or refused — both are sub-second locally).
const Duration fastCloseWindow = Duration(seconds: 3);

/// The credential-rejection re-check cadence.
const Duration credentialRecheckInterval = Duration(seconds: 30);

/// Decrypts a DM produced by [encryptDm]. The AAD target is the DM
/// recipient id on both sides — i.e. the decrypting identity's own
/// agentId — so a payload cross-posted to another agent fails the AEAD
/// tag. Throws on wrong key or tampered payload.
Future<String> decryptDm(
  DapIdentity me,
  String senderX25519B64,
  String frameId,
  String ciphertextB64,
) {
  return decryptPayload(
    recipientDhKeyPair: me.dhKeyPair,
    senderDhPubkey: SimplePublicKey(
      base64Decode(senderX25519B64),
      type: KeyPairType.x25519,
    ),
    frameId: frameId,
    aadTarget: me.agentId,
    ciphertextB64: ciphertextB64,
  );
}

/// Placeholder delivered instead of dropping a payload we cannot decrypt —
/// key missing, peer unknown, or a broken/tampered box (never silent loss).
String undecryptableText(String from) =>
    '[hub] undecryptable message from $from';

/// Sliding seen-set over `(from, text)` pairs, shared by the bridge and
/// DAP mail paths so one peer message arriving on both links is delivered
/// once (AC18 — the bridge copy lands first and the DAP copy is dropped).
/// ponytail: insertion-ordered set as LRU ring; no timestamps needed.
final class MailDeduper {
  MailDeduper({this.capacity = 512});

  final int capacity;
  final _seen = <String>{};

  /// Whether [from]/[text] was not seen recently (and is now recorded).
  bool first(String from, String text) {
    final key = '$from\u0000$text';
    if (!_seen.add(key)) return false;
    if (_seen.length > capacity) _seen.remove(_seen.first);
    return true;
  }
}

/// Agent-host wiring for the DAP hub (issue #23 G3): resolves (or creates
/// and persists) the extension identity, runs one [DapClient], feeds
/// decrypted inbound mail into the host's shared mail intake, and exposes
/// the agent-facing tools (`dap_dm`, `dap_peers`).
library;

import 'dart:async';

import 'package:flutter_agent_harness/src/agent/agent_loop.dart'
    show ToolExecutionResult;
import 'package:flutter_agent_harness/src/agent/agent_tool.dart';
import 'package:flutter_agent_harness/src/approval/approval.dart';

import 'dap_client.dart';
import 'dap_frames.dart';
import 'bound_session_routing.dart';

/// faDap settings from chrome.storage plus the persistence seams for the
/// identity key file (stored as `faDapKey` in the key-file format, so an
/// export stays byte-compatible with the CLI's `~/.dap` identity).
final class DapConfig {
  DapConfig({
    required this.url,
    required this.name,
    required this.loadKeyFile,
    required this.saveKeyFile,
    this.secret = '',
    this.clientSecret = '',
    this.channel = '',
    this.channelPub,
    this.channelPriv,
    this.boundSessionMode = kDefaultBoundSessionMode,
    this.boundSessionId,
    this.persistBoundSessionId,
  });

  final String url;

  /// Display name for the hello (cosmetic; ids are how peers address us).
  final String name;

  /// The hub password (faDap.secret), sent as the
  /// `dap_token` query param on the WS upgrade — browser WebSocket cannot
  /// set headers, and the loopback hub accepts the query form. Empty =
  /// open hub.
  final String secret;

  /// Hub-issued enrollment credential, sent as `?token=` by the worker.
  final String clientSecret;

  /// The single active enrolled channel. Empty = ordinary hub presence.
  final String channel;
  final String? channelPub;
  final String? channelPriv;

  final Future<String?> Function() loadKeyFile;
  final Future<void> Function(String) saveKeyFile;

  /// Inbound hub-mail routing (`faDap.boundSession.mode`):
  /// `dedicated` (the DEFAULT — one agent-owned 'DAP Inbox' session,
  /// created lazily on first mail; `current` and `named` are opt-in),
  /// `current` (mail lands in the open session),
  /// `named` (a user-picked session id in [boundSessionId]).
  final String boundSessionMode;

  /// The pinned session for `dedicated` (once created) / `named` modes.
  final String? boundSessionId;

  /// Persists the lazily created dedicated session id back into the
  /// config (chrome.storage `faDap.boundSession.sessionId`) so the same
  /// session keeps receiving mail across SW restarts.
  final Future<void> Function(String sessionId)? persistBoundSessionId;

  /// Stable across reconnects/restarts: same config (url+name) keeps the
  /// live client instead of dropping the connection.
  bool sameTargetAs(DapConfig other) =>
      url == other.url &&
      name == other.name &&
      secret == other.secret &&
      clientSecret == other.clientSecret &&
      channel == other.channel &&
      channelPub == other.channelPub &&
      channelPriv == other.channelPriv;
}

/// Owns the extension's hub presence for one [DapConfig]. Created by
/// [AgentHost] when faDap config exists; disposed on reconfigure.
final class DapIntegration {
  DapIntegration({
    required this.config,
    required this.pushMail,
    required this.onStatusChanged,
  });

  final DapConfig config;
  final void Function(String from, String text) pushMail;
  final void Function() onStatusChanged;

  DapClient? _client;
  Map<String, dynamic> _status = const {'phase': 'disconnected'};

  /// Latest hub status for the host's state snapshot (null = no hub).
  /// Reports even when the client never came up — a silent failure is
  /// undebuggable from outside the service worker.
  Map<String, dynamic>? snapshot() => _status;

  late final AgentTool dapDm = AgentTool(
    name: 'dap_dm',
    description:
        'Send an end-to-end encrypted direct message to a peer on the DAP '
        'hub. "to" is the peer\'s exact 16-hex agent id, or a unique ONLINE '
        'display name (list them with dap_peers). Replies arrive as '
        '"[from <agentId>]" mail at the next turn boundary.',
    parameters: const {
      'type': 'object',
      'properties': {
        'to': {'type': 'string'},
        'text': {'type': 'string'},
      },
      'required': ['to', 'text'],
    },
    tier: ApprovalTier.exec,
    execute: (arguments, cancelToken, onUpdate) async {
      final to = '${arguments['to'] ?? ''}'.trim();
      final text = '${arguments['text'] ?? ''}';
      if (to.isEmpty || text.isEmpty) {
        throw ArgumentError('dap_dm needs non-empty "to" and "text"');
      }
      final client = _requireClient();
      return ToolExecutionResult.text(await client.sendDm(to, text));
    },
  );

  late final AgentTool dapPeers = AgentTool(
    name: 'dap_peers',
    description:
        'List agents currently ONLINE on the DAP hub, one "<name> <agentId>" '
        'per line. Use an id with dap_dm.',
    parameters: const {'type': 'object', 'properties': {}},
    tier: ApprovalTier.read,
    execute: (arguments, cancelToken, onUpdate) async {
      final agents = await _requireClient().presence();
      final online = [
        for (final agent in agents)
          if (agent['online'] == true)
            '${agent['name'] ?? '(unnamed)'} ${agent['agentId']}',
      ];
      return ToolExecutionResult.text(
        online.isEmpty ? 'no agents online' : online.join('\n'),
      );
    },
  );

  List<AgentTool> get tools => [dapDm, dapPeers];

  /// Resolves the identity (loading or generating + persisting it), then
  /// starts the client. Quiet on failure — the status reflects it.
  Future<void> start() async {
    try {
      // Never print the configured URL: enrollment configurations may carry
      // credentials in their query, and diagnostics must stay secret-free.
      print('[dap] start: name=${config.name.isEmpty ? '—' : config.name}');
      final stored = await config.loadKeyFile();
      final identity = stored != null
          ? await DapIdentity.fromKeyFile(stored)
          : await _freshIdentity();
      print(
        '[dap] identity ${stored != null ? 'loaded' : 'generated'}: '
        '${identity.agentId}',
      );
      final client = DapClient(
        identity: identity,
        url: config.url,
        name: config.name,
        secret: config.secret,
        clientSecret: config.clientSecret,
        channel: config.channel,
        channelPub: config.channelPub,
        channelPriv: config.channelPriv,
        onMail: pushMail,
        onStatus: (status) {
          _status = status.toMap();
          onStatusChanged();
        },
      );
      _client = client;
      client.start();
    } on Object catch (e) {
      // A silent hub-presence failure is undebuggable — the console is the
      // only window into a service worker. Surface what actually broke.
      print('[fa] dap identity/start failed: $e');
      _status = {
        'phase': 'disconnected',
        'reason': 'identity unavailable',
        'error': '$e',
      };
      onStatusChanged();
    }
  }

  Future<void> stop() async {
    final client = _client;
    _client = null;
    await client?.stop();
  }

  DapClient _requireClient() {
    final client = _client;
    if (client == null) throw StateError('hub is not configured');
    return client;
  }

  Future<DapIdentity> _freshIdentity() async {
    final identity = await DapIdentity.generate();
    await config.saveKeyFile(await identity.toKeyFile());
    return identity;
  }
}

// Service worker entry (classic script — MV3 classic SW; dart2js agent.js is
// classic too, so importScripts works for everything). Owns: pairing storage,
// bridge wiring, panel API, and the embedded fa agent (self-contained mode).
//
// Load order matters: tabs.js before ops.js (namespace destructure), agent.js
// is optional (scaffold checkouts without a dart build stay fully functional).
importScripts('./tabs.js', './bridge.js', './ops.js', './cdp.js', './fetch_bridge.js');
// Service workers have no `window`, but package:cryptography's web backend
// probes window.crypto (WebCrypto itself IS available here via self.crypto).
// Alias it before the dart2js bundle initializes any crypto lazily.
self.window = self;
try {
  importScripts('./agent.js'); // dart2js output; absent → scaffold mode
} catch {
  console.warn('[fa] sw/agent.js not built — embedded agent disabled');
}
const { bridge, KEEPALIVE_ALARM } = globalThis.faSw;
const { dispatch } = globalThis.faSw;
const tabs = globalThis.faSw;

const PANEL_PORT = 'fa-panel';
const AGENT_ALARM = 'fa-agent-keepalive';
const ports = new Set();
const agent = globalThis.faAgent ?? null;

// Panels render agent-derived state (e.g. the paste staging cap) from the
// status snapshot, but the fa-panel port only pushes on bridge activity. A
// boot (or boot failure) changes that state without any bridge traffic, so
// push a fresh snapshot when the seam's boot settles - otherwise panels keep
// the pre-boot "no agent" view until the next unrelated push.
if (agent && typeof agent.boot === 'function') {
  const seamBoot = agent.boot.bind(agent);
  agent.boot = (config) => {
    const result = seamBoot(config);
    Promise.resolve(result)
      .finally(() => {
        try {
          pushPanels({ type: 'status', status: snapshot() });
        } catch {}
      })
      .catch(() => {});
    return result;
  };
}

const store = {
  get: (keys) => chrome.storage.local.get(keys),
  set: (o) => chrome.storage.local.set(o),
  remove: (keys) => chrome.storage.local.remove(keys),
};

function pushPanels(msg) {
  // Sender hygiene (issue #470): a panel port can die without its
  // onDisconnect having run yet — one dead port must not throw through the
  // event that is pushing to it, so prune it instead.
  for (const port of [...ports]) {
    try {
      port.postMessage(msg);
    } catch {
      ports.delete(port);
    }
  }
}

function snapshot() {
  return {
    ...bridge.status(),
    task: tabs.status(),
    ...(agent ? { agent: agent.getState() } : {}),
  };
}

// A composer enrollment is complete only after the worker's existing client
// received the hub's joined ack. Poll status without ever logging the URL,
// credential, invite keys, or raw server errors.
async function waitForHubJoin(channel) {
  const deadline = Date.now() + 10000;
  while (Date.now() < deadline) {
    const hub = agent?.getState()?.hub;
    if (hub?.joinFailed || hub?.phase === 'unauthorized') {
      return { ok: false, error: 'hub rejected the enrollment' };
    }
    if (hub?.phase === 'connected' && Array.isArray(hub.channels) && hub.channels.includes(channel)) {
      return { ok: true };
    }
    await new Promise((resolve) => setTimeout(resolve, 100));
  }
  return { ok: false, error: 'hub channel join timed out' };
}

// Browser op table for the embedded agent (same ops as the wire protocol).
globalThis.__faOps = (op, args) => dispatch(op, args || {});

// The toolbar icon opens the side panel (docs/browser-extension.md "Load
// it" step 3). Without this the action click is a silent no-op: no
// default_popup, no onClicked handler — the headless suite never noticed
// because it opens panel.html by URL.
chrome.sidePanel
  .setPanelBehavior({ openPanelOnActionClick: true })
  .catch((e) => console.error('fa: setPanelBehavior failed', e));

// Bridge disconnect ends the task (contract AC17: cleanup on task_end OR disconnect).
let wasConnected = false;
bridge.onStatus((s) => {
  pushPanels({ type: 'status', status: snapshot() });
  if (s.phase === 'connected') {
    wasConnected = true;
    tabs.beginTask(crypto.randomUUID()); // task id = connection session uuid
  } else if (wasConnected) {
    wasConnected = false;
    tabs.taskEnd();
  }
});

bridge.onMail((m) => {
  pushPanels({ type: 'mail', from: m.from, text: m.text, msgId: m.msgId });
  // Test-only inbound-mail log for the headless CI suite: polls it to prove
  // fabric→browser delivery (no panel needed). Routing fields only; capped.
  const mailLog = (globalThis.__faMailLog ??= []);
  mailLog.push({ from: m.from, text: m.text, ts: m.ts ?? Date.now() });
  if (mailLog.length > 50) mailLog.shift();
  agent?.pushMail(m.from, m.text); // bridge mail reaches the embedded agent
});

bridge.onBrowserReq(async (req) => {
  const out = await dispatch(req.req ?? req.op, req.args || {}); // browser op name arrives as `req` (envelope op is "browserReq")
  bridge.browserRes(req.id, out); // exactly one answer per browserReq
});

// Embedded agent events → panel push; keepalive re-arm on run start/end (E8).
let agentRunning = false;
function armAgentAlarm(running) {
  if (running === agentRunning) return;
  agentRunning = running;
  if (running) chrome.alarms.create(AGENT_ALARM, { periodInMinutes: 0.5 });
  else chrome.alarms.clear(AGENT_ALARM);
}

if (agent) {
  agent.onEvent((ev) => {
    if (ev?.type === 'status') armAgentAlarm(!!ev.running);
    pushPanels({ type: 'agent', event: ev });
  });
}

// Panel API (request/response over runtime messaging).
chrome.runtime.onMessage.addListener((msg, _sender, sendResponse) => {
  (async () => {
    switch (msg?.type) {
      case 'status':
        return { ok: true, status: snapshot() };
      case 'pair': {
        if (!msg.url || !msg.token) return { ok: false, error: 'bridge url and token are required' };
        await store.set({ bridgeUrl: msg.url, token: msg.token });
        bridge.connect(msg.url, msg.token);
        return { ok: true };
      }
      case 'unpair':
        await store.remove(['bridgeUrl', 'token']);
        await bridge.disconnect();
        return { ok: true };
      case 'sendTest':
        try {
          await bridge.sendMail(msg.to || 'main', msg.text || '');
          return { ok: true };
        } catch (e) {
          return { ok: false, error: String(e.message || e) };
        }
      case 'agent.send':
        if (!agent) return { ok: false, error: 'agent not built (missing sw/agent.js)' };
        agent.sendUser(String(msg.text ?? ''));
        return { ok: true };
      case 'agent.decide':
        if (!agent) return { ok: false, error: 'agent not built (missing sw/agent.js)' };
        agent.decide(String(msg.id ?? ''), !!msg.allow);
        return { ok: true };
      case 'provider.save': {
        const provider = {
          baseUrl: String(msg.baseUrl ?? '').trim(),
          apiKey: String(msg.apiKey ?? ''),
          model: String(msg.model ?? '').trim(),
        };
        await store.set({ faProvider: provider, ...(msg.approvalMode ? { faApproval: msg.approvalMode } : {}) });
        // boot() rebuilds the whole config — pass the stored hub + approval
        // back so saving the provider never drops the hub connection.
        const cur = await store.get(['faApproval', 'faDap']);
        agent?.boot({ provider, approvalMode: cur.faApproval, dap: cur.faDap });
        return { ok: true };
      }
      case 'hub.join': {
        // Composer DAP enrollment rides the worker's existing DapClient —
        // never a panel-local WebSocket (a second connection would evict the
        // worker). One active enrollment mirrors the native app controller.
        if (!agent) return { ok: false, error: 'agent not built (missing sw/agent.js)' };
        const url = String(msg.url ?? '').trim();
        const channel = String(msg.channel ?? '').trim();
        const clientSecret = typeof msg.clientSecret === 'string' ? msg.clientSecret : '';
        const pub = typeof msg.pub === 'string' ? msg.pub : null;
        const priv = typeof msg.priv === 'string' ? msg.priv : null;
        if (!url || !channel || (pub === null) !== (priv === null)) {
          return { ok: false, error: 'invalid enrollment' };
        }
        const prev = (await store.get(['faDap'])).faDap;
        const next = {
          url,
          name: String(msg.name ?? '').trim(),
          ...(prev?.boundSession ? { boundSession: prev.boundSession } : {}),
          ...(Array.isArray(prev?.savedConnections) ? { savedConnections: prev.savedConnections } : {}),
          enrollment: {
            channel,
            ...(clientSecret ? { clientSecret } : {}),
            ...(pub !== null ? { pub, priv } : {}),
          },
        };
        await store.set({ faDap: next });
        const cur = await store.get(['faProvider', 'faApproval']);
        await agent.boot({ provider: cur.faProvider, approvalMode: cur.faApproval, dap: next });
        return await waitForHubJoin(channel);
      }
      case 'hub.save': {
        // faDap {url, name, secret?, boundSession?, savedConnections?}; empty
        // url = no hub presence. Identity keys are generated + stored inside
        // the Dart agent (faDapKey) on first start. The session binding
        // (boundSession) is edited via hub.bind — saving the connection
        // preserves it. savedConnections (the multi-hub bookmark list) is
        // managed by hub.connections.set / hub.switch — always preserved.
        // secret = the hub password; an empty field keeps the stored one.
        const url = String(msg.url ?? '').trim();
        const name = String(msg.name ?? '').trim();
        const prev = (await store.get(['faDap'])).faDap;
        const boundSession = prev && prev.boundSession ? { boundSession: prev.boundSession } : {};
        const savedConnections = prev && Array.isArray(prev.savedConnections) ? { savedConnections: prev.savedConnections } : {};
        const enteredSecret = String(msg.secret ?? '');
        const keptSecret = prev && typeof prev.secret === 'string' ? prev.secret : '';
        const next = { url, name, ...boundSession, ...savedConnections };
        const effectiveSecret = enteredSecret || keptSecret;
        if (effectiveSecret) next.secret = effectiveSecret;
        if (url) await store.set({ faDap: next });
        else await store.remove(['faDap']);
        console.log('[dap-hub] connection saved:', url || '(cleared)', 'saved list:', (next.savedConnections ?? []).length);
        const cur = await store.get(['faProvider', 'faApproval']);
        agent?.boot({ provider: cur.faProvider, approvalMode: cur.faApproval, dap: url ? next : null });
        return { ok: true };
      }
      case 'hub.connections.set': {
        // Multi-hub bookmarks: overwrite faDap.savedConnections wholesale
        // (the page owns list editing). Each entry: {url, name, secret?} —
        // an entry WITHOUT a secret key means an open hub (secret cleared
        // on switch); a non-empty secret rides along. Inert for the live
        // agent — no reboot.
        const cur = (await store.get(['faDap'])).faDap;
        if (!cur || !cur.url) return { ok: false, error: 'no hub connection' };
        const list = (Array.isArray(msg.list) ? msg.list : [])
          .map((e) => {
            const entry = { url: String(e?.url ?? '').trim(), name: String(e?.name ?? '').trim() };
            if (typeof e?.secret === 'string' && e.secret) entry.secret = e.secret;
            return entry;
          })
          .filter((e) => e.url);
        const next = { ...cur, savedConnections: list };
        await store.set({ faDap: next });
        console.log('[dap-hub] saved connections list set:', list.length);
        return { ok: true, count: list.length };
      }
      case 'hub.switch': {
        // Make a bookmarked connection active: same path as hub.save, but
        // the secret comes from the entry — an entry without a secret key
        // is an open hub, so the stored password is CLEARED (keep-secret
        // semantics would leak the previous hub's password into it).
        const target = String(msg.url ?? '').trim();
        const prev = (await store.get(['faDap'])).faDap;
        const list = prev && Array.isArray(prev.savedConnections) ? prev.savedConnections : [];
        const entry = list.find((e) => e && e.url === target);
        if (!entry) return { ok: false, error: 'connection not bookmarked: ' + target };
        const next = {
          url: entry.url,
          name: String(entry.name ?? ''),
          ...(prev.boundSession ? { boundSession: prev.boundSession } : {}),
          ...(entry.secret ? { secret: entry.secret } : {}),
          savedConnections: list,
        };
        await store.set({ faDap: next });
        console.log('[dap-hub] switched active connection →', entry.url);
        const cur = await store.get(['faProvider', 'faApproval']);
        agent?.boot({ provider: cur.faProvider, approvalMode: cur.faApproval, dap: next });
        return { ok: true };
      }
      case 'hub.bind.get': {
        // Read side for the panel's routing picker (issue #321): routing
        // fields ONLY — {mode, sessionId?, title?}. The hub secret (and
        // everything else in faDap) never crosses to the UI — 'UI holds
        // no keys'. Null binding = nothing saved yet (panel default:
        // dedicated).
        const cur = (await store.get(['faDap'])).faDap;
        const bound = cur?.boundSession;
        if (!bound?.mode) return { ok: true, binding: null };
        const binding = { mode: String(bound.mode) };
        if (bound.sessionId) binding.sessionId = String(bound.sessionId);
        if (bound.title) binding.title = String(bound.title);
        return { ok: true, binding };
      }
      case 'hub.bind': {
        // Inbound-mail routing (faDap.boundSession): {mode: dedicated|current|named, sessionId?, title?}.
        // Merged into faDap — url/name/secret/savedConnections stay untouched.
        // EVERY mode persists a binding ('current' included — {mode:'current'}
        // — so the panel choice round-trips sticky instead of silently
        // snapping back to dedicated on the next read). Default mode:
        // dedicated, the #304 owner UX.
        const cur = (await store.get(['faDap'])).faDap;
        if (!cur || !cur.url) return { ok: false, error: 'no hub connection to bind' };
        // Default AND fallback for a garbled mode: dedicated — same contract
        // as the panel picker and the Dart config layer (issue #321).
        const mode = ['dedicated', 'current', 'named'].includes(msg.mode)
          ? msg.mode
          : 'dedicated';
        const prev = cur.boundSession ?? {};
        const next = {
          url: String(cur.url),
          name: String(cur.name ?? ''),
          ...(cur.secret ? { secret: cur.secret } : {}), // the hub password survives rebinds
          ...(cur.enrollment ? { enrollment: cur.enrollment } : {}),
          ...(Array.isArray(cur.savedConnections) ? { savedConnections: cur.savedConnections } : {}),
        };
        next.boundSession = { mode };
        if (mode === 'dedicated' || mode === 'named') {
          if (msg.sessionId) next.boundSession.sessionId = String(msg.sessionId);
          if (msg.title) next.boundSession.title = String(msg.title);
          // A dedicated rebind that keeps the session id but sends no title
          // preserves the minted one ('DAP Inbox') — the title stays visible.
          else if (mode === 'dedicated' && prev.mode === 'dedicated' && prev.title) {
            next.boundSession.title = String(prev.title);
          }
        }
        await store.set({ faDap: next });
        const prov = await store.get(['faProvider', 'faApproval']);
        agent?.boot({ provider: prov.faProvider, approvalMode: prov.faApproval, dap: next });
        return { ok: true, binding: next.boundSession };
      }
      case 'hub.sessions': {
        if (!agent || !agent.sessionsList) return { ok: true, sessions: [] };
        return { ok: true, sessions: agent.sessionsList() || [] };
      }
      case 'providers.import': {
        // .fahx import (issue #34 item 3): the Dart agent owns the decrypt;
        // a wrong passphrase or tampered file fails loudly, nothing written.
        if (!agent) return { ok: false, error: 'agent not built (missing sw/agent.js)' };
        const out = await agent.importFahx(String(msg.contents ?? ''), String(msg.passphrase ?? ''));
        return out;
      }
      case 'tools.set': {
        // Second-tier power tools (issue #34 AC4d): store the enabled map,
        // then push it into the live agent — the gate re-applies there.
        const enabled = {};
        for (const [name, on] of Object.entries(msg.enabled ?? {})) {
          if (on === true) enabled[name] = true;
        }
        await store.set({ faBrowserTools: enabled });
        agent?.applyToolVisibility(enabled);
        return { ok: true, enabled };
      }
      default:
        return { ok: false, error: `unknown message type "${msg?.type}"` };
    }
  })().then(
    (r) => {
      try {
        sendResponse(r);
      } catch {} // the asker's frame died mid-flight (OWA rebuilds them constantly) — nothing to answer
    },
    (e) => {
      // Never an uncaught rejection (issue #470): surface as the one answer.
      try {
        sendResponse({ ok: false, error: String(e?.message || e) });
      } catch {}
    },
  );
  return true; // async sendResponse
});

